<template>
  <section class="candidate-page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 7 · CANDIDATE EXPANSION</p><h2>黄金卡候选补齐计划</h2><p>把12个缺失片型的60个固定 benchmark 项目转为可填写槽位，验证片型合同、事实边界和来源授权。</p></div><nav><RouterLink to="/story/stage7-golden-card-review">真人审稿接入</RouterLink><RouterLink to="/story/stage6-operations">Stage 6 总控</RouterLink></nav></header>
    <div class="truth-lock"><strong>槽位 ≠ 候选卡 ≠ 黄金卡</strong><span>模板、benchmark、fixture 和验证 ready 都不计候选成稿、人工通过或专业进度。</span></div>
    <p v-if="errorMessage" class="error-banner">{{ errorMessage }}</p>
    <section v-if="workspace" class="summary-grid"><article><span>缺失片型</span><strong>{{ workspace.summary.missing_video_type_count }}</strong></article><article><span>计划槽位</span><strong>{{ workspace.summary.planned_slot_count }}</strong></article><article><span>已填写候选</span><strong>0</strong></article><article><span>导入 ready</span><strong>0</strong></article><article class="zero"><span>人工通过</span><strong>0</strong></article></section>
    <section v-if="workspace" class="type-grid"><article v-for="item in workspace.video_types" :key="item.video_type" :class="item.status"><span>{{ item.label }}</span><strong>{{ item.current_candidate_count }} + {{ item.planned_slot_count }} slots</strong><small>{{ item.status==='already_has_candidate_coverage'?'已有候选，不建槽位':'缺5张，仅准备槽位' }}</small></article></section>
    <section v-if="workspace" class="control-bar"><label>候选槽位<select v-model="selectedSlotId"><option v-for="slot in workspace.slots" :key="slot.slot_id" :value="slot.slot_id">{{ slot.video_type_label }} · {{ slot.source_entry }} · {{ slot.benchmark_id }}</option></select></label><button :disabled="loading" @click="loadWorkspace">生成绑定模板</button><button class="primary" :disabled="loading||!editorText" @click="runInspection">{{ loading?'验证中…':'验证候选 JSON' }}</button></section>
    <section class="workspace-grid">
      <article class="editor-card"><header><div><p class="eyebrow">CANDIDATE JSON</p><h3>外部填写候选</h3></div><span>仅内存</span></header><div class="toolbar"><label>导入 JSON<input type="file" accept=".json,application/json" @change="importFile"></label><button @click="copyJson">复制 JSON</button><span>{{ copyMessage }}</span></div><textarea v-model="editorText" aria-label="Stage 7 golden card candidate JSON" spellcheck="false"/><footer><span>{{ editorText.length.toLocaleString() }} 字符</span><b>不生成 · 不落盘 · 不批准</b></footer></article>
      <article class="result-card"><header><div><p class="eyebrow">VALIDATION RESULT</p><h3>槽位、片型与证据门禁</h3></div><b :class="inspection?.candidate_ready_for_external_human_review?'ready':'blocked'">{{ inspection?.candidate_ready_for_external_human_review?'READY FOR HUMAN REVIEW':'BLOCKED' }}</b></header>
        <div v-if="inspection" class="metrics"><div><span>Schema</span><strong>{{ inspection.checks.candidate_schema_valid?'合法':'失败' }}</strong></div><div><span>字段</span><strong>{{ inspection.content_summary.filled_material_field_count }}/{{ inspection.content_summary.required_material_field_count }}</strong></div><div><span>来源</span><strong>{{ inspection.content_summary.source_reference_count }}</strong></div><div><span>人工通过</span><strong>0</strong></div></div>
        <div v-if="inspection" class="binding-panel"><span>Slot <b>{{ inspection.expected_binding.slot_id }}</b></span><span>片型 <b>{{ inspection.expected_binding.video_type }}</b></span><span>Benchmark <b>{{ inspection.expected_binding.benchmark_id }}</b></span><span>条目 <b>{{ inspection.expected_binding.source_entry }}</b></span><span>Project SHA <code>{{ shortHash(inspection.benchmark_project_sha256) }}</code></span><span>Profile SHA <code>{{ shortHash(inspection.profile_contract_sha256) }}</code></span></div>
        <section v-if="inspection" class="required"><h4>片型必填字段</h4><div><span v-for="field in inspection.expected_binding.required_material_fields" :key="field">{{ field }}</span></div></section>
        <section v-if="inspection" class="checks"><h4>候选导入门禁</h4><div><span v-for="(passed,key) in inspection.checks" :key="key" :class="passed?'ok':'fail'">{{ passed?'✓':'×' }} {{ checkLabel(key) }}</span></div></section>
        <section v-if="inspection?.issues.length" class="issues"><h4>问题 {{ inspection.issues.length }} 项</h4><article v-for="(item,index) in inspection.issues" :key="`${item.code}-${index}`"><header><b>{{ item.gate.toUpperCase() }}</b><code>{{ item.code }}</code></header><span>{{ item.path||'root' }}</span><p>{{ item.message }}</p></article></section>
        <div class="safety-grid"><span>Candidate persisted <b>否</b></span><span>Index modified <b>否</b></span><span>Card file created <b>否</b></span><span>Province Markdown modified <b>否</b></span><span>Golden card promoted <b>否</b></span><span>Professional passed <b>否</b></span></div>
      </article>
    </section>
  </section>
</template>

<script setup lang="ts">
import { onMounted,ref } from 'vue'
import type { Stage7GoldenCardCandidateInspectionResult,Stage7GoldenCardCandidateWorkspace } from '@shared/types'
import { getStage7GoldenCardCandidateWorkspace,inspectStage7GoldenCardCandidate } from '../api/stage7-golden-cards'
const workspace=ref<Stage7GoldenCardCandidateWorkspace|null>(null),inspection=ref<Stage7GoldenCardCandidateInspectionResult|null>(null),selectedSlotId=ref(''),editorText=ref(''),loading=ref(false),errorMessage=ref(''),copyMessage=ref('')
const labels:Record<string,string>={request_valid:'检查请求',json_valid:'JSON 可解析',candidate_schema_valid:'Candidate schema',slot_found:'60槽位计划存在',target_video_type_still_missing_candidates:'目标片型仍缺候选',slot_id_binding_valid:'Slot ID 绑定',candidate_id_binding_valid:'Candidate ID 绑定',video_type_binding_valid:'片型绑定',benchmark_binding_valid:'Benchmark 绑定',source_entry_binding_valid:'知识条目绑定',benchmark_file_binding_valid:'Benchmark 文件绑定',benchmark_file_digest_valid:'Benchmark 文件 SHA',benchmark_project_digest_valid:'项目 Payload SHA',profile_contract_digest_valid:'GenreProfile 合同 SHA',required_material_fields_present:'片型字段齐全',required_material_fields_filled:'片型字段已填写',visible_actions_present:'可见动作',verified_facts_present:'已核事实',source_refs_present:'来源引用',forbidden_claims_present:'禁用断言',source_entry_confirmed:'知识条目已确认',source_authorization_resolved:'来源/授权已解决',candidate_status_valid:'候选状态与来源',source_claimed_credit_rejected:'自报信用已拒绝'}
onMounted(loadWorkspace)
async function loadWorkspace(){loading.value=true;errorMessage.value='';const response=await getStage7GoldenCardCandidateWorkspace(selectedSlotId.value);loading.value=false;if(!response.ok||!response.data){errorMessage.value=response.error?.message??'候选补齐计划加载失败';return}workspace.value=response.data;selectedSlotId.value=response.data.selected_slot_id;editorText.value=response.data.template_raw_json;inspection.value=response.data.template_inspection}
async function runInspection(){loading.value=true;errorMessage.value='';const response=await inspectStage7GoldenCardCandidate({raw_json:editorText.value,expected_slot_id:selectedSlotId.value});loading.value=false;if(!response.ok||!response.data){errorMessage.value=response.error?.message??'候选 JSON 验证失败';return}inspection.value=response.data}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{editorText.value=await file.text();errorMessage.value=''}catch(error){errorMessage.value=`导入失败：${(error as Error).message}`}finally{input.value=''}}
async function copyJson(){try{await navigator.clipboard.writeText(editorText.value);copyMessage.value='已复制'}catch{copyMessage.value='复制未授权'}window.setTimeout(()=>copyMessage.value='',1600)} function checkLabel(key:string){return labels[key]??key} function shortHash(value:string){return value?`${value.slice(0,10)}…${value.slice(-6)}`:'—'}
</script>

