lid #47766f;border-radius:7px;color:#e2f0ed;background:#071312}.control-bar .primary{background:#247063;border-color:#5cb5a5}.control-bar button:disabled{opacity:.5}.workspace-grid{max-width:1480px;margin:auto;display:grid;grid-template-columns:minmax(420px,.86fr) minmax(590px,1.14fr);gap:15px;align-items:start}.editor-card,.result-card{overflow:hidden;border:1px solid #315e58;border-radius:13px;background:rgba(12,31,29,.97)}.editor-card{position:sticky;top:15px}.editor-card>header,.result-card>header{padding:15px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #274b47}.editor-card h3,.result-card h3{margin:3px 0 0}.editor-card header span{color:#789892;font:10px ui-monospace,monospace}.result-card header>b{font-size:10px;letter-spacing:.07em}.ready{color:#75dbc2}.blocked{color:#ff97a5}.toolbar{padding:10px 13px;display:flex;align-items:center;gap:7px}.toolbar input{display:none}.toolbar span{color:#789891;font-size:10px}textarea{width:100%;min-height:680px;padding:16px;box-sizing:border-box;resize:vertical;border:0;border-block:1px solid #23413e;outline:0;color:#d7e8e4;background:#050d0d;font:11px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.editor-card footer{padding:10px 13px;display:flex;justify-content:space-between;color:#789891;font-size:10px}.editor-card footer b{color:#76cdbb}.metrics{margin:14px;display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.metrics div{padding:9px;border-radius:7px;background:#16332f}.metrics span{display:block;color:#7fa59e;font-size:9px}.metrics strong{font-size:15px}.metrics div:last-child strong{color:#ff9ca8}.binding-panel,.safety-grid{margin:0 14px 12px;display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.binding-panel span,.safety-grid span{padding:8px;border-radius:7px;color:#7fa49d;background:#142d2a;font-size:9px}.binding-panel b,.binding-panel code,.safety-grid b{float:right;max-width:65%;color:#d6e7e3;overflow-wrap:anywhere}.safety-grid b{color:#ff9ca8}.required,.check