@media(max-width:1150px){.type-grid{grid-template-columns:repeat(4,1fr)}.workspace-grid{grid-template-columns:1fr}.editor-card{position:static}textarea{min-height:460px}}@media(max-width:760px){.candidate-page{padding:18px 12px}.hero,.truth-lock,.control-bar{align-items:flex-start;flex-direction:column}.control-bar label{width:100%}.summary-grid{grid-template-columns:repeat(2,1fr)}.type-grid{grid-template-columns:repeat(2,1fr)}.metrics,.binding-panel,.safety-grid,.checks>div{grid-template-columns:1fr}}
</style>
